tape( 'the function computes `sin(πx)` and `cos(πx)` (integer values)', function test( t ) {
	var out;
	var x;
	var s;
	var c;
	var y;
	var i;

	x = integers.x;
	s = integers.sin;
	c = integers.cos;
	for ( i = 0; i < x.length; i++ ) {
		out = new Float32Array( 2 );
		y = sincospif( x[ i ], out, 1, 0 );
		t.strictEqual( y, out, 'returns output array' );
		t.strictEqual( isSameValuef( y[ 0 ], f32( s[ i ] ) ), true, 'returns expected value' );
		t.strictEqual( isSameValuef( y[ 1 ], f32( c[ i ] ) ), true, 'returns expected value' );
	}
	t.end();
});

